import java.util.Scanner;
import java.util.TreeSet;
import java.util.ArrayList;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            TreeSet<Long> st = new TreeSet<>();
            for (int i = 0; i < n; i++) st.add(sc.nextLong());
            long k = sc.nextLong();
            ArrayList<Long> a = new ArrayList<>(st);
            long count = 0, ans = -1;
            for (int i = 0; i + 1 < a.size(); i++) {
                long diff = a.get(i + 1) - a.get(i) - 1;
                if (count + diff >= k) {
                    ans = a.get(i) + (k - count);
                    break;
                }
                count += diff;
            }
            System.out.println(ans);
        }
    }
}

